package com.bank.uuidv7.id;

import java.security.SecureRandom;
import java.util.UUID;

// RFC 9562 UUIDv7: [48-bit ms timestamp][4-bit version=7][2-bit variant][74-bit random]
public class UuidV7 {
    private static final SecureRandom RANDOM = new SecureRandom();

    public static UUID generate() {
        long ts = System.currentTimeMillis();     // 48-bit timestamp prefix
        byte[] b = new byte[16];
        RANDOM.nextBytes(b);
        b[0] = (byte) (ts >>> 40); b[1] = (byte) (ts >>> 32);
        b[2] = (byte) (ts >>> 24); b[3] = (byte) (ts >>> 16);
        b[4] = (byte) (ts >>> 8);  b[5] = (byte) ts;
        b[6] = (byte) ((b[6] & 0x0F) | 0x70);      // version 7
        b[8] = (byte) ((b[8] & 0x3F) | 0x80);      // IETF variant
        long msb = 0, lsb = 0;
        for (int i = 0; i < 8; i++)  msb = (msb << 8) | (b[i] & 0xFF);
        for (int i = 8; i < 16; i++) lsb = (lsb << 8) | (b[i] & 0xFF);
        return new UUID(msb, lsb);
    }

    // Decode the 48-bit timestamp prefix back to epoch milliseconds — proves ordering
    public static long extractTimestampMillis(UUID id) {
        return id.getMostSignificantBits() >>> 16;
    }
}
