package com.bank.uuidv7.service;

import com.bank.uuidv7.id.UuidV7;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.time.Instant;
import java.util.UUID;

@Service
public class TransactionIdService {
    private static final Logger log = LoggerFactory.getLogger(TransactionIdService.class);

    // No DB sequence (unlike auto-increment), no worker-id (unlike Snowflake),
    // but time-ordered (unlike UUIDv4). Unique + ordered + coordination-free.
    public UUID newTransactionId() {
        UUID id = UuidV7.generate();
        long millis = UuidV7.extractTimestampMillis(id);
        log.info("Minted UUIDv7 {} embedding time {} (unique + time-ordered + no coordination)",
                 id, Instant.ofEpochMilli(millis));
        return id;
    }
}
